<style>
.xd5-page .xd6-services-page{padding:48px 0 80px;background:#101012;color:#f7f7f8}
.xd6-services-page>.xd-container{width:min(1240px,calc(100% - 64px));margin-inline:auto}
.xd6-services-page .xd-cms-hero{grid-template-columns:minmax(0,1fr) minmax(220px,.35fr);gap:40px;padding:0 0 36px;margin-bottom:36px;background:transparent;border:0;border-bottom:1px solid #333339;box-shadow:none}
.xd6-services-page .xd-kicker{margin:0 0 16px;color:#ff827b;font-size:12px;font-weight:700;letter-spacing:.1em}
.xd6-services-page .xd-kicker:before{display:none}
.xd6-services-page .xd-cms-hero h1{color:#fff;font-size:clamp(32px,3.5vw,48px);line-height:1.2;letter-spacing:-.025em;overflow-wrap:anywhere}
