@media(max-width:600px){.xd5-page .xd6-services-page{padding:32px 0 48px}.xd6-services-page>.xd-container{width:calc(100% - 32px)}.xd6-services-page .xd-cms-hero{gap:24px;padding-bottom:28px;margin-bottom:28px}.xd6-services-page .xd-cms-hero h1{font-size:32px}.xd6-services-page .xd-cms-stats{padding:18px}.xd6-services-page .xd-services-list{grid-template-columns:minmax(0,1fr)}.xd6-services-page .xd-service-body{padding:24px 20px}}
